<?php
require_once dirname(__DIR__).'/includes/functions.php';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){$email=strtolower(trim($_POST['email']??''));$stmt=$con->prepare("SELECT id,name,email FROM users WHERE email=? AND status='active' AND deleted_at IS NULL");$stmt->bind_param('s',$email);$stmt->execute();if($u=$stmt->get_result()->fetch_assoc()){$token=bin2hex(random_bytes(32));$stmt=$con->prepare("INSERT INTO password_resets(user_id,token,expires_at) VALUES(?,?,DATE_ADD(NOW(),INTERVAL 1 HOUR))");$stmt->bind_param('is',$u['id'],$token);$stmt->execute();try{require_once dirname(__DIR__).'/config/mailer.php';$mail=configured_mailer();$mail->addAddress($u['email'],$u['name']);$mail->Subject='Reset your CareerSim password';$link=(isset($_SERVER['HTTPS'])?'https':'http').'://'.$_SERVER['HTTP_HOST'].url('auth/reset_password.php?token='.$token);$mail->Body='<p><a href="'.e($link).'">Reset your password</a>. This link expires in one hour.</p>';$mail->send();}catch(Throwable $e){}}$message='If that account exists, a password reset link has been sent.';}
$pageTitle='Reset password';require dirname(__DIR__).'/includes/header.php';?><div class="container py-5"><div class="card p-4 mx-auto" style="max-width:480px"><h1 class="h3">Forgot your password?</h1><?php if($message):?><div class="alert alert-success"><?=e($message)?></div><?php endif?><form method="post"><label class="form-label">Account email</label><input type="email" name="email" class="form-control mb-3" required><button class="btn btn-primary w-100">Send reset link</button></form></div></div><?php require dirname(__DIR__).'/includes/footer.php';?>
